[asy]
unitsize(0.5 cm);

pair A, B, C, D, E;
real x = 250/39;

A = (0,8);
B = (-6,0);
C = (6,0);
D = interp(A,B,x/10);
E = interp(A,C,(10 - x)/10);

draw(A--B--C--cycle);
draw(D--E);

label("$A$", A, N);
label("$B$", B, SW);
label("$C$", C, SE);;
label("$D$", D, NW);
label("$E$", E, NE);

label("$x$", (A + D)/2, NW);
label("$x$", (D + E)/2, SE);
label("$x$", (C + E)/2, NE);
label("$10 - x$", (A + E)/2, NE);
[/asy]

